const express = require('express');
const app = express();
const products = [{ id: 1, name: 'Widget', price: 500 }];

app.get('/products', (req, res) => {
  const q = req.query.q || '';
  res.json(products.filter(p => p.name.includes(q)));
});

app.post('/products', (req, res) => {
  products.push(req.body);
  res.json(req.body);
});

app.listen(3000);
